/* @lc app=leetcode id=2751 lang=kotlin */ class Solution { fun survivedRobotsHealths(positions: IntArray, healths: IntArray, directions: String): List<Int> = mutableListOf<Int>().let { s -> positions.indices.sortedBy { positions[it] }.forEach { i -> intArrayOf(i).let { c -> run { while (c[0] != -1 && s.isNotEmpty() && directions[s.last()] == 'R' && directions[c[0]] == 'L') { if (healths[s.last()] > healths[c[0]]) { run { healths[s.last()] = healths[s.last()] - 1 }.run { healths[c[0]] = 0 }.run { c[0] = -1 } } else if (healths[s.last()] < healths[c[0]]) { run { healths[c[0]] = healths[c[0]] - 1 }.run { healths[s.removeAt(s.size - 1)] = 0 } } else { run { healths[s.removeAt(s.size - 1)] = 0 }.run { healths[c[0]] = 0 }.run { c[0] = -1 } } } }.run { if (c[0] != -1) s.add(c[0]) } } }.run { healths.filter { it > 0 } } } }